namespace sv_c43c15faaf4343c3b5f5a442ccf438fd.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds theme state per circuit.
/// All interactive components on the same circuit share this instance.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@implements IDisposable
@inject ThemeService ThemeService

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass(ThemeMode.Light)" @onclick="() => SetTheme(ThemeMode.Light)">☀️ Light</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.Dark)" @onclick="() => SetTheme(ThemeMode.Dark)">🌙 Dark</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.System)" @onclick="() => SetTheme(ThemeMode.System)">💻 System</button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void SetTheme(ThemeMode mode)
    {
        ThemeService.Theme = mode;
    }

    private string ButtonClass(ThemeMode mode) =>
        ThemeService.Theme == mode ? "btn-primary" : "btn-outline-secondary";

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <ThemeToggle />

        <h5 class="card-title mt-4">Accent Color</h5>
        <div class="d-flex align-items-center gap-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <span style="color: @ThemeService.AccentColor; font-weight: bold;">
                @ThemeService.AccentColor
            </span>
        </div>

        <div class="mt-4 p-3 border rounded" style="border-color: @ThemeService.AccentColor !important;">
            <strong>Preview:</strong> Current theme is <em>@ThemeService.Theme</em>
            with accent <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

